    })

useForm({
        quote_currency: '',
        rate_date: new Date().toISOString().slice(0, 10),
        rate: '',
        source: 'manual',
    })

useForm({
        warehouse_id: '',
        product_id: '',
        counted_quantity: '',
        count_date: today,
    })

